import{_ as t,o as e,c as a,a5 as s}from"./chunks/framework.BmD0ICqc.js";const o="/study/images/os/operating-system-basics.svg",g=JSON.parse('{"title":"OSの役割 — アプリとハードウェアをつなぐ","description":"","frontmatter":{"title":"OSの役割 — アプリとハードウェアをつなぐ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"ゲームとブラウザーを同時に動かす場面から、OSがCPU時間、メモリ、ファイル、機器を管理する仕事を説明する。カーネル、プロセス、スレッドの意味もつなげる。","aliases":["OS","operating system","オペレーティングシステム","基本ソフトウェア","カーネル","プロセス","スレッド","ドライバー","マルチタスク"],"verification":"Microsoftのプロセス・メモリ・ユーザーモードとカーネルモード・ドライバーの資料に照合（2026-11-07）"}},"headers":[],"relativePath":"os/operating-system-basics.md","filePath":"os/operating-system-basics.md"}'),n={name:"os/operating-system-basics.md"};function i(d,r,l,h,c,m){return e(),a("div",null,[...r[0]||(r[0]=[s('<h1 id="osの役割-—-アプリとハードウェアをつなぐ" tabindex="-1">OSの役割 — アプリとハードウェアをつなぐ <a class="header-anchor" href="#osの役割-—-アプリとハードウェアをつなぐ" aria-label="Permalink to &quot;OSの役割 — アプリとハードウェアをつなぐ&quot;">​</a></h1><p>OS（Operating System）は、アプリがCPU、メモリ、ファイル、機器を使うための共通の仕組みを提供するソフトウェアです。Windows、macOS、Linuxなどがあります。ゲームとブラウザーを一緒に開くときも、OSはそれぞれのプログラムを動かし、必要な資源を管理します。ここではWindowsを主な例にします。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/windows-kernel-mode-process-and-thread-manager" target="_blank" rel="noreferrer">MicrosoftのWindowsアーキテクチャー</a> · <a href="/study/hardware/computer-components.html">コンピュータの部品と役割</a></p><h2 id="アプリがする仕事と、osが受け持つ仕事" tabindex="-1">アプリがする仕事と、OSが受け持つ仕事 <a class="header-anchor" href="#アプリがする仕事と、osが受け持つ仕事" aria-label="Permalink to &quot;アプリがする仕事と、OSが受け持つ仕事&quot;">​</a></h2><p>ゲームはキャラクターの位置やルールを決めます。OSはその処理を実行させ、メモリやファイルなどを使うための機能を提供します。アプリがOSの機能を呼ぶための窓口を<strong>API</strong>と呼びます。例えばWindowsの<code>ReadFile</code>は、開いたファイルからデータを読むAPIです。<a href="https://learn.microsoft.com/en-us/windows/win32/apiindex/windows-api-list" target="_blank" rel="noreferrer">MicrosoftのWindows API</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-readfile" target="_blank" rel="noreferrer">ReadFile</a></p><table tabindex="0"><thead><tr><th>OSが受け持つこと</th><th>ゲームとブラウザーを動かす場面</th></tr></thead><tbody><tr><td><strong>CPU時間の割り当て</strong></td><td>実行できるスレッドから次に動かすものを選び、CPUで処理を進める。</td></tr><tr><td><strong>メモリの管理</strong></td><td>各アプリが使うアドレス空間と、必要なメモリの対応を管理する。</td></tr><tr><td><strong>ファイルの管理</strong></td><td>名前やディレクトリからファイルを開き、読み書きする機能を提供する。</td></tr><tr><td><strong>機器とのやり取り</strong></td><td>ドライバーなどを通して、ストレージ、ネットワーク、入力機器を利用する。</td></tr><tr><td><strong>権限の確認</strong></td><td>利用者やアプリに、そのファイルや資源を操作する権限があるかを調べる。</td></tr></tbody></table><figure class="study-figure"><img src="'+o+'" alt="ゲームとブラウザーは別のプロセスとして動き、それぞれにメモリのアドレス空間を持つ。OSがCPU時間、メモリ、ファイル、機器を管理し、CPU・RAM・SSD・NICなどのハードウェアを利用する。" width="760" height="460" loading="lazy"><figcaption>役割の概念図です。アプリの処理もOSの処理も、実際にはCPUが命令を実行して進みます。<a href="/study/images/os/operating-system-basics.svg" target="_blank" rel="noopener noreferrer">OSの役割の図を拡大</a></figcaption></figure><h2 id="プログラム、プロセス、スレッド" tabindex="-1">プログラム、プロセス、スレッド <a class="header-anchor" href="#プログラム、プロセス、スレッド" aria-label="Permalink to &quot;プログラム、プロセス、スレッド&quot;">​</a></h2><p><strong>プログラム</strong>は実行する命令やデータです。保存された<code>game.exe</code>を起動すると、Windowsは実行に必要な資源をまとめた<strong>プロセス</strong>を作ります。同じEXEを二回起動すれば、通常は別々のプロセスになります。<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoftのプロセスとスレッド</a></p><p><strong>スレッド</strong>は、プロセスの中で命令の実行を進め、OSが実行先を割り当てる単位です。一つのプロセスには少なくとも一つのスレッドがあり、追加もできます。同じプロセスのスレッドは、そのプロセスのメモリや開いた資源を共有します。<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoftのプロセスとスレッド</a></p><p>CPUの実行先より多くのスレッドがあっても、OSは実行するものを切り替えて処理を進められます。複数のコアがあれば、複数のスレッドを同時に実行することもできます。入力やファイルの完了を待っているスレッドは、再び実行できる状態になるまで待機します。<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/multitasking" target="_blank" rel="noreferrer">Microsoftのマルチタスク</a> · <a href="/study/os/thread-scheduling.html">スレッドスケジューリング</a></p><h2 id="カーネルとユーザーモード" tabindex="-1">カーネルとユーザーモード <a class="header-anchor" href="#カーネルとユーザーモード" aria-label="Permalink to &quot;カーネルとユーザーモード&quot;">​</a></h2><p>OSの中心で、資源の管理などを担当する部分を<strong>カーネル</strong>と呼びます。Windowsの通常のアプリは<strong>ユーザーモード</strong>で動き、OSの中核部分は<strong>カーネルモード</strong>で動きます。カーネルモードには、アプリから直接使えないメモリなどへアクセスする権限があります。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/user-mode-and-kernel-mode" target="_blank" rel="noreferrer">Microsoftのユーザーモードとカーネルモード</a></p><p>各プロセスには、自分が使う<strong>仮想アドレス空間</strong>があります。例えばゲームとブラウザーで同じ数値のアドレスを使っても、同じデータを指すとは限りません。共有メモリなどを明示的に使う場合には、別プロセス間でデータを共有できます。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/virtual-address-space" target="_blank" rel="noreferrer">Microsoftの仮想アドレス空間</a> · <a href="/study/os/virtual-memory.html">仮想メモリ</a></p><p>アプリがファイルの操作などを依頼するとき、OSの保護された処理へ移る入口を使います。この仕組みが<strong>システムコール</strong>です。ライブラリの関数が呼ばれるたびに必ず一回のシステムコールが起きるかは、その関数の実装や扱うデータによって変わります。<a href="/study/os/system-calls-and-privilege.html">システムコールと権限</a></p><h2 id="ドライバーと機器" tabindex="-1">ドライバーと機器 <a class="header-anchor" href="#ドライバーと機器" aria-label="Permalink to &quot;ドライバーと機器&quot;">​</a></h2><p><strong>ドライバー</strong>は、OSと機器の間で、機器に応じた操作や結果の受け渡しを担当するソフトウェアです。Windowsではカーネルモードで動くドライバーも、ユーザーモードで動くドライバーもあります。例えばNICの受信では、ドライバーがデータを回収してOSの通信処理へ渡します。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/what-is-a-driver-" target="_blank" rel="noreferrer">Microsoftのドライバー</a> · <a href="/study/hardware/io/nic-receive-queues.html">NICの受信経路</a></p><h2 id="ゲームの起動から見る" tabindex="-1">ゲームの起動から見る <a class="header-anchor" href="#ゲームの起動から見る" aria-label="Permalink to &quot;ゲームの起動から見る&quot;">​</a></h2><ol><li>OSがプロセスと最初のスレッドを用意する。</li><li>必要なプログラムやデータを使えるようにして、CPUで命令を実行する。</li><li>ゲームがファイル、入力、描画、通信などの機能を利用する。</li><li>終了時に、開いた資源やメモリを解放する。</li></ol><p>詳しい起動処理は<a href="/study/os/process-startup.html">実行ファイルを起動してmainへ到達するまで</a>、ファイルの基本は<a href="/study/os/files-and-paths.html">ファイルとパス</a>へ進めます。コマンドからアプリを起動する操作は<a href="/study/tools/terminal-shell-and-commands.html">ターミナル・シェル・コマンド</a>で扱います。</p>',19)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
